//! Differential test against the TS validators.
//!
//! Replays `test/__rs/core-validate/fixtures/validations.json` (generated by
//! `TZ=UTC pnpm tsx test/__rs/core-validate/generate.ts`): every validator result, every host
//! interaction log, the `t` function cases and the JS builtin corpora must match exactly.
//! Run the test with the `TZ` the fixture was generated with (it is checked): local date-times
//! go through the process time zone like V8 (`payload_core_validate::tz`).
//!
//! `RS_CORE_VALIDATE_FIXTURE` overrides the fixture path, `RS_CORE_VALIDATE_VERBOSE=1` prints
//! up to 50 mismatches per section.

use std::cell::RefCell;
use std::path::PathBuf;

use payload_core_validate::date::{LocalTz, date_parse};
use payload_core_validate::i18n::t;
use payload_core_validate::js::{json_stringify, number_to_string, parse_float_str, string_to_number};
use payload_core_validate::validations::is_valid_email;
use payload_core_validate::{
  FilterOptionsCall, FindArgs, I18n, Req, ValidateHost, ValidationResult, Validator, validate,
};
use payload_engine::error::{EngineError, Result};
use payload_engine::js::{JsVal, Obj, date_to_iso_string, decode_graph_typed};
use serde_json::Value as Json;

fn fixture_path() -> PathBuf {
  std::env::var("RS_CORE_VALIDATE_FIXTURE").map(PathBuf::from).unwrap_or_else(|_| {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("../../test/__rs/core-validate/fixtures/validations.json")
  })
}

fn verbose() -> bool {
  std::env::var("RS_CORE_VALIDATE_VERBOSE").is_ok_and(|v| v == "1")
}

fn dec(json: &Json) -> JsVal {
  decode_graph_typed(&serde_json::json!({ "objects": [], "root": json })).expect("decodable fixture value")
}

fn obj<const N: usize>(entries: [(&str, JsVal); N]) -> JsVal {
  JsVal::obj(entries.into_iter().map(|(k, v)| (k.to_string(), v)).collect())
}

const RESERVED: &[&str] = &["$date", "$fn", "$num", "$obj", "$ref", "$undefined"];

/// The process time zone (what V8 uses).
struct ProcessTz;

impl LocalTz for ProcessTz {
  fn local_to_utc(&self, local_ms: i64) -> f64 {
    payload_core_validate::tz::local_to_utc(local_ms)
  }
}

/// The fixture must come from a run in the same `TZ` as this test.
fn check_tz(fixture: &Json) {
  let tz = std::env::var("TZ").ok();
  assert_eq!(fixture["meta"]["tz"].as_str(), tz.as_deref(), "run the test with the fixture's TZ");
}

/// The generator's `enc` (the `serializeForEngine` format without references).
fn enc(v: &JsVal) -> JsVal {
  match v {
    JsVal::Undefined => obj([("$undefined", JsVal::Bool(true))]),
    JsVal::Num(n) if !n.is_finite() => obj([("$num", JsVal::str(number_to_string(*n)))]),
    JsVal::Fn(id) => obj([("$fn", JsVal::Num(f64::from(*id)))]),
    JsVal::Obj(_) if v.as_date().is_some() => {
      obj([("$date", v.as_date().and_then(date_to_iso_string).map(JsVal::str).unwrap_or(JsVal::Null))])
    }
    JsVal::Arr(a) => JsVal::arr(a.iter().map(enc).collect()),
    JsVal::Obj(o) => {
      let out: Obj = o.iter().map(|(k, v)| (k.clone(), enc(v))).collect();
      if out.len() == 1 && RESERVED.contains(&out.keys().next().map(String::as_str).unwrap_or("")) {
        obj([("$obj", JsVal::obj(out))])
      } else {
        JsVal::obj(out)
      }
    }
    other => other.clone(),
  }
}

fn enc_str(v: &JsVal) -> String {
  json_stringify(&enc(v)).expect("encodable").unwrap_or_default()
}

fn same_number(a: f64, b: f64) -> bool {
  (a.is_nan() && b.is_nan()) || a.to_bits() == b.to_bits()
}

fn error_key(e: &EngineError) -> String {
  if e.name == "Error" { format!("!Error:{}", e.message) } else { format!("!{}", e.name) }
}

fn type_error(msg: &str) -> EngineError {
  EngineError::new("TypeError", msg)
}

/// Mirrors the generator's host mocks (functions are identified by registration order).
struct MockHost<'a> {
  calls: RefCell<Vec<JsVal>>,
  user: JsVal,
  json_schema_results: &'a serde_json::Map<String, Json>,
  /// `String(date)` by time value.
  date_strings: Vec<(f64, String)>,
}

const OBJECT_PROTOTYPE_KEYS: &[&str] = payload_core_validate::js::OBJECT_PROTOTYPE_KEYS;

fn db(collection: &str) -> Option<Vec<JsVal>> {
  Some(match collection {
    "media" => vec![JsVal::str("507f1f77bcf86cd799439011"), JsVal::str("m1"), JsVal::str("m2")],
    "nums" => vec![JsVal::Num(1.0), JsVal::Num(2.0), JsVal::Num(3.0)],
    "posts" => vec![JsVal::Num(1.0), JsVal::Num(2.0), JsVal::Num(3.0), JsVal::str("abc"), JsVal::Num(5.0)],
    _ => return None,
  })
}

fn includes(list: &JsVal, item: &JsVal) -> Result<bool> {
  let JsVal::Arr(items) = list else { return Err(type_error("includes is not a function")) };
  Ok(items.iter().any(|v| payload_core_validate::js::same_value_zero(v, item)))
}

impl ValidateHost for MockHost<'_> {
  fn filter_options(&self, func: u32, call: FilterOptionsCall<'_>) -> Result<JsVal> {
    let args = match &call {
      FilterOptionsCall::Blocks { id, data, sibling_data } => obj([
        ("id", (*id).clone()),
        ("data", (*data).clone()),
        ("siblingData", (*sibling_data).clone()),
        ("user", self.user.clone()),
      ]),
      FilterOptionsCall::Relationship { id, block_data, data, relation_to, sibling_data } => obj([
        ("id", (*id).clone()),
        ("blockData", (*block_data).clone()),
        ("data", (*data).clone()),
        ("relationTo", (*relation_to).clone()),
        ("siblingData", (*sibling_data).clone()),
        ("user", self.user.clone()),
      ]),
      FilterOptionsCall::Select { data, options, sibling_data } => obj([
        ("data", (*data).clone()),
        ("options", (*options).clone()),
        ("siblingData", (*sibling_data).clone()),
      ]),
    };
    self.calls.borrow_mut().push(JsVal::arr(vec![JsVal::str("filterOptions"), JsVal::Num(f64::from(func)), enc(&args)]));

    let not_in = |ids: Vec<JsVal>| obj([("id", obj([("not_in", JsVal::arr(ids))]))]);
    Ok(match func {
      0 | 8 => JsVal::Bool(true),
      1 => JsVal::Bool(false),
      2 => not_in(vec![JsVal::Num(2.0), JsVal::str("m1")]),
      3 => return Err(EngineError::internal("boom")),
      4 => {
        if args.get("relationTo").as_str() == Some("media") {
          JsVal::Bool(false)
        } else {
          obj([("id", obj([("equals", JsVal::Num(1.0))]))])
        }
      }
      5 => JsVal::Null,
      6 => JsVal::str("weird"),
      7 => not_in(vec![JsVal::Num(3.0)]),
      9 => JsVal::arr(vec![JsVal::str("a"), JsVal::str("b")]),
      10 => JsVal::arr(vec![]),
      11 => return Err(EngineError::internal("blocks boom")),
      12 => JsVal::obj(Obj::new()),
      13 => {
        let JsVal::Arr(options) = args.get("options") else { return Err(type_error("options.filter")) };
        JsVal::arr(
          options
            .iter()
            .filter(|o| {
              let v = if matches!(o, JsVal::Str(_)) { (*o).clone() } else { payload_core_validate::js::get_opt(o, "value") };
              !v.strict_eq(&JsVal::str("b"))
            })
            .cloned()
            .collect(),
        )
      }
      14 => JsVal::arr(vec![JsVal::str("a"), JsVal::str("c")]),
      15 => return Err(EngineError::internal("select boom")),
      16 => JsVal::str("nope"),
      17 => match payload_core_validate::js::get_opt(args.get("siblingData"), "allow") {
        v if v.is_nullish() => JsVal::arr(vec![JsVal::str("a")]),
        v => v,
      },
      _ => return Err(EngineError::internal(format!("unknown mock function {func}"))),
    })
  }

  fn find(&self, args: FindArgs<'_>) -> Result<JsVal> {
    self.calls.borrow_mut().push(JsVal::arr(vec![
      JsVal::str("find"),
      enc(&obj([
        ("collection", args.collection.clone()),
        ("overrideAccess", args.override_access.clone()),
        ("where", args.where_.clone()),
      ])),
    ]));
    let collection = payload_core_validate::js::to_string(args.collection)?;
    if collection == "baddocs" {
      return Ok(obj([("docs", JsVal::str("x"))]));
    }
    if collection == "nulldocs" {
      return Ok(obj([("docs", JsVal::arr(vec![JsVal::Null]))]));
    }
    let docs = match db(&collection) {
      Some(docs) => docs,
      None if OBJECT_PROTOTYPE_KEYS.contains(&collection.as_str()) => return Err(type_error("docs.filter")),
      None => return Err(EngineError::internal(format!("unknown collection {collection}"))),
    };
    let and = args.where_.get("and").as_arr().unwrap_or(&[]).to_vec();
    if and.len() > 2 {
      return Err(EngineError::internal("unsupported where"));
    }
    let in_list = and[0].get("id").get("in").clone();
    let mut ids = Vec::new();
    for id in docs {
      if includes(&in_list, &id)? {
        ids.push(id);
      }
    }
    if let Some(extra) = and.get(1) {
      let extra_id = payload_core_validate::js::get_opt(extra, "id");
      let not_in = payload_core_validate::js::get_opt(&extra_id, "not_in");
      if not_in.truthy() {
        let mut kept = Vec::new();
        for id in ids {
          if !includes(&not_in, &id)? {
            kept.push(id);
          }
        }
        ids = kept;
      } else if extra_id.truthy() {
        let JsVal::Obj(o) = &extra_id else { return Err(type_error("in")) };
        if !o.contains_key("equals") {
          return Err(EngineError::internal("unsupported where"));
        }
        let equals = extra_id.get("equals").clone();
        ids.retain(|id| id.strict_eq(&equals));
      } else {
        return Err(EngineError::internal("unsupported where"));
      }
    }
    Ok(obj([("docs", JsVal::arr(ids.into_iter().map(|id| obj([("id", id)])).collect()))]))
  }

  fn log_error(&self, msg: &str, err: &EngineError) -> Result<()> {
    self.calls.borrow_mut().push(JsVal::arr(vec![JsVal::str("log"), JsVal::str(msg), JsVal::str(err.name.as_str())]));
    Ok(())
  }

  fn validate_json_schema(&self, json_schema: &JsVal, value: &JsVal) -> Result<ValidationResult> {
    let key = format!("{}\u{0}{}", enc_str(json_schema), enc_str(value));
    match self.json_schema_results.get(&key) {
      Some(Json::Bool(true)) => Ok(ValidationResult::Valid),
      Some(Json::String(s)) => Ok(ValidationResult::Invalid(s.clone())),
      other => Err(EngineError::internal(format!("no recorded jsonSchema result for {key}: {other:?}"))),
    }
  }

  fn date_to_string(&self, ms: f64) -> Result<String> {
    self
      .date_strings
      .iter()
      .find(|(time, _)| *time == ms)
      .map(|(_, text)| text.clone())
      .ok_or_else(|| EngineError::internal(format!("no recorded String(date) for {ms}")))
  }

  fn rich_text_validate(&self, editor: &JsVal, value: &JsVal, _options: &JsVal) -> Result<ValidationResult> {
    if !matches!(editor.get("validate"), JsVal::Fn(18)) {
      return Err(type_error("editor.validate is not a function"));
    }
    self.calls.borrow_mut().push(JsVal::arr(vec![JsVal::str("richText"), enc(value)]));
    let is_object = matches!(value, JsVal::Obj(_) | JsVal::Arr(_));
    let has_root = matches!(value, JsVal::Obj(o) if o.contains_key("root"));
    if value.truthy() && is_object && has_root {
      Ok(ValidationResult::Valid)
    } else {
      Ok(ValidationResult::Invalid(format!("rich text invalid {}", payload_core_validate::js::type_of(value))))
    }
  }
}

fn load() -> Json {
  let path = fixture_path();
  let text = std::fs::read_to_string(&path).unwrap_or_else(|e| {
    panic!("missing fixture {} ({e}); run `TZ=UTC pnpm tsx test/__rs/core-validate/generate.ts`", path.display())
  });
  serde_json::from_str(&text).expect("valid fixture json")
}

#[test]
fn validators_match_ts() {
  let fixture = load();
  let strings: Vec<&str> = fixture["strings"].as_array().unwrap().iter().map(|s| s.as_str().unwrap()).collect();
  let values: Vec<JsVal> = fixture["values"].as_array().unwrap().iter().map(dec).collect();
  let payloads: Vec<JsVal> = fixture["payloads"].as_array().unwrap().iter().map(dec).collect();
  let i18n = I18n { translations: dec(&fixture["translations"]) };
  let json_schema_results = fixture["jsonSchemaResults"].as_object().unwrap();
  check_tz(&fixture);
  let date_strings = fixture["primitives"]["dateToString"]
    .as_array()
    .unwrap()
    .iter()
    .map(|case| (case[0].as_f64().unwrap(), case[1].as_str().unwrap().to_string()))
    .collect();
  let host =
    MockHost { calls: RefCell::new(Vec::new()), user: dec(&fixture["user"]), json_schema_results, date_strings };

  let mut total = 0;
  let mut mismatches = 0;
  let mut call_mismatches = 0;
  let mut report = Vec::new();

  for validator_fixture in fixture["validators"].as_array().unwrap() {
    let name = validator_fixture["name"].as_str().unwrap();
    let validator = Validator::from_name(name).unwrap_or_else(|| panic!("unknown validator {name}"));
    let call_logs = validator_fixture["callLogs"].as_object().unwrap();
    let mut validator_mismatches = 0;
    for (config_index, (options_json, (payload_index, results))) in validator_fixture["options"]
      .as_array()
      .unwrap()
      .iter()
      .zip(validator_fixture["payloads"].as_array().unwrap().iter().zip(validator_fixture["results"].as_array().unwrap()))
      .enumerate()
    {
      let options = dec(options_json);
      let payload = &payloads[payload_index.as_u64().unwrap() as usize];
      let req = Req {
        config: payload.get("config"),
        collections: payload.get("collections"),
        default_id_type: payload.get("db").get("defaultIDType"),
        t: &i18n,
        host: &host,
      };
      for (value_index, (value, expected)) in values.iter().zip(results.as_array().unwrap()).enumerate() {
        total += 1;
        host.calls.borrow_mut().clear();
        let expected = expected.as_u64().unwrap() as usize;
        let expected = if expected == 0 { "true" } else { strings[expected] };
        let actual = match validate(validator, value, &options, &req) {
          Ok(ValidationResult::Valid) => "true".to_string(),
          Ok(ValidationResult::Invalid(s)) => s,
          Err(e) => error_key(&e),
        };
        let calls = host.calls.borrow();
        let actual_calls = if calls.is_empty() { None } else { json_stringify(&JsVal::arr(calls.clone())).unwrap() };
        let expected_calls =
          call_logs.get(&format!("{config_index}:{value_index}")).map(|i| strings[i.as_u64().unwrap() as usize].to_string());
        let result_ok = actual == expected;
        let calls_ok = actual_calls == expected_calls;
        if !result_ok {
          mismatches += 1;
          validator_mismatches += 1;
        }
        if !calls_ok {
          call_mismatches += 1;
        }
        if (!result_ok || !calls_ok) && report.len() < 50 {
          report.push(format!(
            "{name} config #{config_index} {} value {}:\n  expected {expected:?}\n  actual   {actual:?}\n  expected calls {expected_calls:?}\n  actual calls   {actual_calls:?}",
            enc_str(&options),
            enc_str(value)
          ));
        }
      }
    }
    if validator_mismatches > 0 {
      eprintln!("{name}: {validator_mismatches} result mismatches");
    }
  }

  eprintln!("validator cases: {total}, result mismatches: {mismatches}, host-call mismatches: {call_mismatches}");
  if verbose() || mismatches + call_mismatches > 0 {
    for line in report.iter().take(if verbose() { 50 } else { 10 }) {
      eprintln!("{line}");
    }
  }
  assert!(total > 1_000_000, "fixture too small: {total}");
  assert_eq!((mismatches, call_mismatches), (0, 0));
}

#[test]
fn translations_match_ts() {
  let fixture = load();
  let sets = fixture["t"]["sets"].as_object().unwrap();
  let sets: std::collections::HashMap<&str, JsVal> = sets.iter().map(|(k, v)| (k.as_str(), dec(v))).collect();
  let cases = fixture["t"]["cases"].as_array().unwrap();
  let mut mismatches = Vec::new();
  for case in cases {
    let set = case[0].as_str().unwrap();
    let key = case[1].as_str().unwrap();
    let vars = dec(&case[2]);
    let expected = case[3].as_str().unwrap();
    let actual = match t(key, &sets[set], vars.as_obj()) {
      Ok(s) => s,
      Err(e) if e.name == "Error" && e.message.contains("non-string value (") => {
        let kind = e.message.rsplit_once('(').map(|(_, k)| k.trim_end_matches(')')).unwrap_or("");
        format!("!nonstring:{kind}")
      }
      Err(e) => error_key(&e),
    };
    if actual != expected {
      mismatches.push(format!("[{set}] t({key:?}, {}): expected {expected:?}, actual {actual:?}", enc_str(&vars)));
    }
  }
  eprintln!("t cases: {}, mismatches: {}", cases.len(), mismatches.len());
  for m in mismatches.iter().take(if verbose() { 50 } else { 10 }) {
    eprintln!("{m}");
  }
  assert!(cases.len() > 10_000);
  assert!(mismatches.is_empty());
}

#[test]
fn builtins_match_v8() {
  let fixture = load();
  check_tz(&fixture);
  let p = &fixture["primitives"];
  let num = |j: &Json| f64::from_bits(u64::from_str_radix(j.as_str().expect("hex bits"), 16).expect("hex bits"));
  let mut failures = Vec::new();
  let mut total = 0;

  for case in p["dateParse"].as_array().unwrap() {
    total += 1;
    let s = case[0].as_str().unwrap();
    let (expected, actual) = (num(&case[1]), date_parse(s, &ProcessTz));
    if !same_number(expected, actual) {
      failures.push(format!("Date.parse({s:?}): expected {expected}, actual {actual}"));
    }
  }
  for case in p["number"].as_array().unwrap() {
    total += 1;
    let s = case[0].as_str().unwrap();
    let (n, f) = (num(&case[1]), num(&case[2]));
    if !same_number(n, string_to_number(s)) {
      failures.push(format!("Number({s:?}): expected {n}, actual {}", string_to_number(s)));
    }
    if !same_number(f, parse_float_str(s)) {
      failures.push(format!("parseFloat({s:?}): expected {f}, actual {}", parse_float_str(s)));
    }
  }
  for case in p["numberToString"].as_array().unwrap() {
    total += 1;
    let n = num(&case[0]);
    let expected = case[1].as_str().unwrap();
    if number_to_string(n) != expected {
      failures.push(format!("String({n:e}): expected {expected}, actual {}", number_to_string(n)));
    }
  }
  for case in p["email"].as_array().unwrap() {
    total += 1;
    let s = case[0].as_str().unwrap();
    if is_valid_email(s) != case[1].as_bool().unwrap() {
      failures.push(format!("emailRegex.test({s:?}): expected {}", case[1]));
    }
  }

  eprintln!("builtin cases: {total}, mismatches: {}", failures.len());
  for f in failures.iter().take(if verbose() { 50 } else { 10 }) {
    eprintln!("{f}");
  }
  assert!(failures.is_empty());
}
